def triples_sum_to_zero(l: list):
    from collections import Counter

    def check_triplets_sum_to_zero(triplets):
        for triplet in triplets:
            if sum(triplet) == 0:
                return True
        return False

    if len(l) < 3:
        return False

    num_count = Counter(l)
    nums = [num for num, count in num_count.items() if count >= 3] + [num for num, count in num_count.items() if count >= 1]

    def generate_triplets(nums):
        triplets = []
        for i in range(len(nums)):
            for j in range(i+1, len(nums)):
                for k in range(j+1, len(nums)):
                    triplets.append((nums[i], nums[j], nums[k]))
        return triplets

    all_triplets = generate_triplets(nums)
    return check_triplets_sum_to_zero(all_triplets)

